insert into operations.escala_dia
  (bar_id, data, funcao_id, pessoa_nome, slot, entra, sai, horas, marcador, turno, origem)
select 3,
       to_date(b.d,'YYYYMMDD'),
       fn.id,
       p.nome,
       b.s,
       (substr(b.e,1,2)||':'||substr(b.e,3,2))::time,
       (substr(b.x,1,2)||':'||substr(b.x,3,2))::time,
       b.h::numeric,
       b.m,
       -- mesma regra do parser: só o sábado é partido em DIA/NOITE
       (case when extract(dow from to_date(b.d,'YYYYMMDD')) = 6 and b.e is not null
             then case when substr(b.e,1,2)::int < 14 then 'dia' else 'noite' end
             else 'unico' end)::operations.operacao_turno,
       'planilha'
from bruto b
join pessoa p on p.c = b.f and p.slot = b.s
join operations.operacao_funcao fn on fn.bar_id = 3 and fn.codigo = p.codigo
on conflict (bar_id, data, funcao_id, slot) do update
   set pessoa_nome = excluded.pessoa_nome, entra = excluded.entra, sai = excluded.sai,
       horas = excluded.horas, marcador = excluded.marcador, turno = excluded.turno,
       origem = 'planilha', atualizado_em = now();

-- ---------- lote 3/5 ----------
with pessoa(c, codigo, slot, nome) as (values ('g','garcom',1,'NAYARA'),('g','garcom',2,'MATHEUS MONTENEGRO'),('g','garcom',3,'MARCELO'),('g','garcom',4,'KAMILLA'),('g','garcom',5,'VIVIAN'),('g','garcom',6,'WENDEL'),('g','garcom',7,'PHELIPE'),('g','garcom',8,'MATHEUS TEIXEIRA'),('g','garcom',9,'LAUANE'),('c','cumim',1,'ALEXANDRE'),('c','cumim',2,'DOUGLAS'),('c','cumim',3,'GEOVANNA'),('c','cumim',4,'BEATRIZ'),('c','cumim',5,'KLEY'),('c','cumim',6,'FABRICIO'),('c','cumim',7,'ALEXANDRE'),('c','cumim',8,'RUBI'),('h','host',1,'PAULA RODRIGUES'),('h','host',2,'PAULO EMANOEL'),('h','host',3,'JHULY'),('a','asg',1,'LACERDA'),('a','asg',2,'JOÃO PIRES'),('a','asg',3,'RIAN'),('a','asg',4,'FRANCINETE'),('b','bartender',1,'MATHEUS'),('b','bartender',2,'GUSTAVO'),('b','bartender',3,'DAKOTA'),('b','bartender',4,'HELIO'),('b','bartender',5,'ISABEL'),('b','bartender',6,'DANILO'),('k','barback',1,'ANA CLARA'),('k','barback',2,'RENAN'),('k','barback',3,'BRUNO'),('k','barback',4,'CLIFF'),('z','cozinha',1,'BRUNA'),('z','cozinha',2,'ANA JULIA'),('z','cozinha',3,'HADASSA'),('z','cozinha',4,'RAQUEL'),('z','cozinha',5,'GABIZINHA'),('z','cozinha',6,'VIVIAN'),('l','lideranca',1,'ANDREIA'),('l','lideranca',2,'DUDU'),('l','lideranca',3,'LUAN'),('l','lideranca',4,'RENATO'),('l','lideranca',5,'LUCIA'),('s','seguranca',1,'DANIEL'),('s','seguranca',2,'MARCWS'),('p','producao',1,'Marla'),('p','producao',2,'Aninha')),
bruto as (
  select split_part(l,'|',1) d, split_part(l,'|',2) f, split_part(l,'|',3)::smallint s,
         nullif(split_part(l,'|',4),'') e, nullif(split_part(l,'|',5),'') x,
         nullif(split_part(l,'|',6),'') h, nullif(split_part(l,'|',7),'') m
  from unnest(string_to_array($blob$
